package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.os.*;import android.media.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.*;
public class InterruptionRecoveryTest extends Instrumentation {
    void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String message)throws Exception{long end=SystemClock.elapsedRealtime()+45000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean yes=new AtomicBoolean();ui(()->yes.set(condition.getAsBoolean()));if(yes.get())return;Thread.sleep(60);}throw new AssertionError(message);}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;AudioFocusRequest rival=null;AudioManager manager=getTargetContext().getSystemService(AudioManager.class);File file=new File(getTargetContext().getFilesDir(),"book_interrupt_recovery_qa.txt");boolean passed=false;try{
        StringBuilder source=new StringBuilder();for(int n=1;n<=3;n++){source.append("第").append(n).append("章 山间的风\n");for(int i=0;i<35;i++)source.append("风吹过山间，书页轻轻翻动。戴上耳机，让每一段文字都有声音。\n");}String text=source.toString();try(FileOutputStream out=new FileOutputStream(file)){out.write(text.getBytes(StandardCharsets.UTF_8));}
        Intent intent=new Intent(getTargetContext(),MainActivity.class).putExtra("book_id","interrupt_recovery_qa").putExtra("book_name","播放恢复验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        activity=(MainActivity)startActivitySync(intent);final MainActivity a=activity;await(()->a.offlineReady&&a.system.initialized&&!a.text.isEmpty(),"reader not ready");ui(()->{a.readingLanguage="";a.loopPlayback=false;a.rate=1.8f;a.systemVoiceKey=a.system.offlineVoice("zh","").key;a.position=a.chapters.get(1).start+120;a.showPosition(true);a.startReading();});await(()->a.playing&&PlaybackService.active!=null&&PlaybackService.active.audioGuard.held&&a.focusGeneration==a.generation,"focus not obtained");
        rival=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setOnAudioFocusChangeListener(change->{},new Handler(Looper.getMainLooper())).build();final AudioFocusRequest competitor=rival;ui(()->check(manager.requestAudioFocus(competitor)==AudioManager.AUDIOFOCUS_REQUEST_GRANTED,"competing focus denied"));await(()->!a.playing&&PlaybackService.active!=null&&!PlaybackService.active.foreground&&!PlaybackService.active.audioGuard.held,"focus interruption did not pause");int bookmark=a.position;manager.abandonAudioFocusRequest(rival);Thread.sleep(800);ui(()->check(!a.playing&&a.position==bookmark,"unexpected auto resume"));result.putBoolean("focusLossPausesWithoutAutoResume",true);
        ui(()->a.startReading());await(()->a.playing&&PlaybackService.active.audioGuard.held,"manual resume failed");ui(()->PlaybackService.active.audioGuard.receiver.onReceive(a,new Intent(AudioManager.ACTION_AUDIO_BECOMING_NOISY)));await(()->!a.playing&&!PlaybackService.active.audioGuard.held,"headphone disconnect did not pause");result.putBoolean("headphoneDisconnectPauses",true);
        ui(()->{a.startReading();a.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);});await(()->a.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE,"rotation missing");ui(()->check(!a.destroyed&&a.playing,"rotation stopped playback"));ui(()->{a.stop();a.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);a.position=a.chapters.get(1).start+240;a.showPosition(true);a.save(true);});final int saved=a.position;final long version=a.checkpointVersion;
        check(ReadingCheckpoint.restore(new File(file+".position"),file.getName(),text,0,0)==saved,"atomic fallback failed");check(ReadingCheckpoint.restore(new File(file+".position"),file.getName(),text,17,version+1)==17,"stale checkpoint overrode newer preferences");check(ReadingCheckpoint.restore(new File(file+".position"),"different.txt",text,19,0)==19,"wrong book checkpoint accepted");ui(()->a.finish());await(()->a.destroyed,"old reader not destroyed");activity=(MainActivity)startActivitySync(intent);final MainActivity reopened=activity;await(()->!reopened.text.isEmpty(),"reopen failed");ui(()->check(reopened.position==saved&&reopened.chapter==1&&!reopened.playing,"bookmark/chapter restore failed"));result.putBoolean("rotationKeepsPlayback",true);result.putBoolean("reopenedReaderRestoresPausedAtBookmark",true);result.putString("result","PASS: competing audio focus; manual resume; unplug pause; rotation; atomic fallback/version/book validation; reader recreation restores chapter and position without autoplay");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(rival!=null)manager.abandonAudioFocusRequest(rival);if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);a.finish();});}file.delete();new File(file+".position").delete();getTargetContext().getSharedPreferences("reader_interrupt_recovery_qa",0).edit().clear().commit();}finish(passed?-1:0,result);}
}
